	public static AnimationDefinition of(DamnedAnim anim) {
		return switch (anim) {
			case IDLE -> IDLE;
			case RUN -> RUN;
			case LEAD -> LEAD;
			case WRITHE -> WRITHE;
			case TUMBLE -> TUMBLE;
			case WALLOW -> WALLOW;
			case PUSH -> PUSH;
			case BRAWL -> BRAWL;
			case BURN -> BURN;
			case BOB -> BOB;
			case SHIVER -> SHIVER;
			case MARCH -> MARCH;
			case SCREAM -> SCREAM;
			case SIGH -> SIGH;
			case FLINCH -> FLINCH;
		};
	}

	/** Every animation, in DamnedAnim's order. */
	public static List<AnimationDefinition> all() {
		return Arrays.stream(DamnedAnim.values()).map(DamnedAnimations::of).toList();
	}
